"""Compact capitals from embedded-graphics FONT_7X13/FONT_7X13_BOLD.

Source: embedded-graphics a293ee30, fonts/raw/ascii/font_7x13{,_bold}.raw.
Keep exact rows 1..10 in a 7x10 cell. Capital ink is nine rows high, hence
18 pixels at 2x. Lowercase aliases capitals to preserve descenders as labels.
No interpolation or bitmap resampling is used.
"""
from base64 import b64decode

_NORMAL = ""
_BOLD = ""


def _rows(encoded):
    raw = b64decode(encoded)
    result = []
    for code in range(32, 127):
        char = chr(code)
        source = char.upper() if char.isascii() and char.islower() else char
        glyph = ord(source) - 32
        for y in range(1, 11):
            value = 0
            for x in range(7):
                bit = (glyph // 16 * 13 + y) * 112 + glyph % 16 * 7 + x
                value = (value << 1) | ((raw[bit // 8] >> (7 - bit % 8)) & 1)
            if char == "_" and y == 10:
                value = 0x7e
            result.append(value)
    return result


UX_FONT_NORMAL = _rows(_NORMAL)
UX_FONT_BOLD = _rows(_BOLD)
